"""Self-reflection, critique, and verification engine for agent planning."""

import re
from typing import Literal

from pydantic import BaseModel, Field

_MAX_SINGLE_STEP_WORDS = 10


class ReflectionCritique(BaseModel):
    """Structured critique output generated by reflection engine."""

    is_viable: bool = Field(..., description="Whether the plan is logically sound and executable.")
    confidence: float = Field(default=1.0, ge=0.0, le=1.0, description="Confidence score between 0.0 and 1.0.")
    risk_level: Literal["low", "medium", "high", "critical"] = Field(
        default="low", description="Assessed risk level."
    )
    strengths: list[str] = Field(default_factory=list, description="Identified strengths in the plan.")
    weaknesses: list[str] = Field(default_factory=list, description="Identified flaws, gaps, or security risks.")
    suggestions: list[str] = Field(default_factory=list, description="Actionable recommendations for improvement.")


class ReflectionEngine:
    """Evaluates agent thought-chains, plans, and tool execution outcomes."""

    def __init__(self, risk_threshold: float = 0.5):
        self.risk_threshold = risk_threshold

    def evaluate_plan(self, goal: str, steps: list[str]) -> ReflectionCritique:
        """Critique an execution plan before execution."""
        if not steps:
            return ReflectionCritique(
                is_viable=False,
                confidence=0.0,
                risk_level="critical",
                weaknesses=["Empty plan provided; no actionable steps."],
                suggestions=["Decompose the goal into concrete atomic actions."],
            )

        weaknesses = []
        strengths = []
        suggestions = []
        risk_level = "low"

        # Heuristic risk and completeness checks
        destructive_keywords = ["rm -rf", "drop table", "truncate", "delete from", "chmod 777", "eval("]
        for step in steps:
            step_lower = step.lower()
            for kw in destructive_keywords:
                if kw in step_lower:
                    weaknesses.append(f"Potentially destructive action detected: '{kw}' in step: '{step}'.")
                    risk_level = "high"

        if len(steps) == 1 and len(goal.split()) > _MAX_SINGLE_STEP_WORDS:
            weaknesses.append("Complex goal attempted in a single monolithic step.")
            suggestions.append("Break down into distinct validation and execution phases.")

        if not weaknesses:
            strengths.append("Plan is concise with well-ordered discrete steps.")
            confidence = 0.95
        else:
            confidence = max(0.2, 1.0 - (len(weaknesses) * 0.25))

        is_viable = confidence >= self.risk_threshold and risk_level != "critical"

        return ReflectionCritique(
            is_viable=is_viable,
            confidence=round(confidence, 2),
            risk_level=risk_level,  # type: ignore[arg-type]
            strengths=strengths,
            weaknesses=weaknesses,
            suggestions=suggestions,
        )

    def critique_action_result(
        self,
        action: str = "",
        result: str = "",
        expected_outcome: str = "",
    ) -> ReflectionCritique:
        """Critique the output of an executed tool action."""
        _ = (action, expected_outcome)  # reserved for semantic evaluation
        res_lower = result.lower()

        # Check for false positives like '0 errors' or 'no errors'
        cleaned = re.sub(r"\b(0|no|without|zero)\s+errors?\b", "", res_lower)
        error_pattern = r"\b(error|exception|failed|denied|traceback|not found)\b"

        has_error = bool(re.search(error_pattern, cleaned))

        if has_error:
            return ReflectionCritique(
                is_viable=False,
                confidence=0.3,
                risk_level="medium",
                weaknesses=[f"Execution produced an error: {result[:120]}..."],
                suggestions=["Inspect parameter values, handle exception, or try an alternative fallback tool."],
            )

        return ReflectionCritique(
            is_viable=True,
            confidence=0.95,
            risk_level="low",
            strengths=["Action succeeded without reported errors."],
            suggestions=[],
        )
